#!/usr/bin/env bash
set -euo pipefail
C="${CEILING1_STAGE2_CONTAINER:?}"; ROOT="${CEILING1_ANALYSIS_ROOT:?}"; WT="${CEILING1_AUTOPILOT_REPO:?}"; ARM="${CEILING1_STAGE2_ARM:?}"; UUID="${CEILING1_STAGE2_GPU_UUID:?}"; ROUND="${CEILING1_STAGE2_ROUND:?}"; GEN="${CEILING1_STAGE2_GENERATION:?}"; DS="${CEILING1_STAGE2_DATASET:?}"; OUT="${CEILING1_STAGE2_SD_ROOT:?}"; EVI="${CEILING1_STAGE2_SD_RECEIPT:?}"; PRIOR="${CEILING1_STAGE2_PRIOR_SD:-}"; PRIORID="${CEILING1_STAGE2_PRIOR_SD_ID:-}"; CFGSHA="${CEILING1_STAGE2_CONFIG_SHA:?}"
CORE="${CEILING1_OPENEVO_CORE_REPO:-/workspace/control/openevo-core}"; CORE_SHA="${CEILING1_OPENEVO_CORE_GIT_SHA:-}"; CAPACITY_POLICY="${CEILING1_STAGE2_CAPACITY_POLICY:-}"; CAPACITY_POLICY_SHA="${CEILING1_STAGE2_CAPACITY_POLICY_SHA256:-}"; prior_mounts=(); if [[ -n "$PRIOR" ]]; then case "$PRIOR" in "$ROOT"/*) ;; *) prior_mounts=(-v "$PRIOR:$PRIOR:ro");; esac; fi; MODEL="$ROOT/stage2-base/$ARM"; case "$ARM" in 3b) MODEL_ID="Qwen/Qwen2.5-3B-Instruct";; 7b) MODEL_ID="Qwen/Qwen2.5-7B-Instruct";; qwen3-1p7b) MODEL_ID="Qwen/Qwen3-1.7B";; *) echo "NO-GO unsupported arm=$ARM" >&2; exit 13;; esac; REV="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["base_revision"])' "$MODEL/merge-receipt.json")"; priorargs=(); [[ -n "$PRIOR" ]] && priorargs=(--prior-adapter "$PRIOR" --prior-artifact-id "$PRIORID"); capargs=(); if [[ -n "$CAPACITY_POLICY" ]]; then [[ "$ARM" == 3b || "$ARM" == qwen3-1p7b ]] || { echo "NO-GO Harness201 capacity policy unsupported arm=$ARM" >&2; exit 14; }; [[ -n "$CORE_SHA" && "$(git -C "$CORE" rev-parse HEAD)" == "$CORE_SHA" && -z "$(git -C "$CORE" status --porcelain)" ]] || { echo "NO-GO Harness201 capacity Core identity drift" >&2; exit 15; }; [[ -f "$CAPACITY_POLICY" && "$(sha256sum "$CAPACITY_POLICY" | awk '{print $1}')" == "$CAPACITY_POLICY_SHA" ]] || { echo "NO-GO Harness201 capacity policy identity drift" >&2; exit 16; }; capargs=(--capacity-policy "$CAPACITY_POLICY" --openevo-core-sha "$CORE_SHA"); fi
docker run -d --name "$C" --restart no --gpus "device=$UUID" --network none --user 1001:1001 -e CUDA_VISIBLE_DEVICES="$UUID" -e TRANSFORMERS_OFFLINE=1 -e HF_HUB_OFFLINE=1 -e PYTHONPATH="$CORE/src:$WT" -v "$CORE:$CORE:ro" -v "$WT:$WT:ro" -v "$ROOT:$ROOT:ro" "${prior_mounts[@]}" -v "$OUT:$OUT" --entrypoint /bin/bash experiment-host/openevo-scientific:h144-runtime-v1 "$WT/scripts/openevo_webshop/ceiling1_sd_lora_pid1_wrapper.sh" "$WT/scripts/openevo_webshop/ceiling1_stage2_sd_lora.py" --dataset-manifest "$DS/manifest.json" --dataset-artifact-id "ceiling1-$ARM-stage2-round-$ROUND" --artifact-root "$OUT/artifacts" --evidence "$EVI" --arm "$ARM" --round-index "$ROUND" --generation-index "$GEN" --python /usr/local/bin/python3 --base-model "$MODEL_ID" --local-model-path "$MODEL" --model-revision "$REV" "${priorargs[@]}" --gpu-uuid "$UUID" --experiment-git-sha "${CEILING1_STAGE2_EXECUTION_GIT_SHA:-$(git -C "$WT" rev-parse HEAD)}" --config-sha256 "$CFGSHA" "${capargs[@]}"
